package com.bank.ctor;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Base class with ONLY an argument-taking constructor. Because we declare this
// constructor, the compiler does NOT generate a no-arg one, which forces every
// subclass to call super(args) explicitly — a half-built account is impossible.
public class Account {
    private static final Logger log = Logger.getLogger(Account.class.getName());

    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    public Account(String accountId, String holderName, BigDecimal balance) {
        if (accountId == null || accountId.isBlank())
            throw new IllegalArgumentException("accountId is mandatory");
        if (balance == null || balance.signum() < 0)
            throw new IllegalArgumentException("balance must be non-negative");
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
        log.fine(() -> "Account base part initialized for " + accountId);
    }

    public void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0)
            throw new IllegalStateException("Insufficient funds in " + accountId);
        balance = balance.subtract(amount);
    }

    public void credit(BigDecimal amount) { balance = balance.add(amount); }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
}
