package com.bank.ctor;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class SavingsAccount extends Account {
    private static final Logger log = Logger.getLogger(SavingsAccount.class.getName());
    private final BigDecimal interestRate;

    // PRIMARY constructor: the single source of truth. It MUST call super(args)
    // first because Account has no no-arg constructor. All real setup lives here.
    public SavingsAccount(String accountId, String holderName, BigDecimal balance, BigDecimal interestRate) {
        super(accountId, holderName, balance); // MUST be first statement
        if (interestRate == null || interestRate.signum() < 0)
            throw new IllegalArgumentException("interestRate must be non-negative");
        this.interestRate = interestRate;
        log.fine(() -> "SavingsAccount part initialized, rate=" + interestRate);
    }

    // CONVENIENCE constructor: delegates to the primary one via this(...).
    // It does NOT call super itself — the primary constructor it delegates to does.
    public SavingsAccount(String accountId, String holderName, BigDecimal balance) {
        this(accountId, holderName, balance, new BigDecimal("0.04")); // default 4% rate
    }

    public BigDecimal getInterestRate() { return interestRate; }
}
