package com.bank.ctor;

import java.math.BigDecimal;
import java.util.logging.*;

public class ConstructorChainDemo {
    private static final Logger log = Logger.getLogger(ConstructorChainDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Built via the convenience constructor: this(...) → primary → super(args).
        SavingsAccount rajesh = new SavingsAccount("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        log.info(() -> "Rajesh account created, default rate=" + rajesh.getInterestRate());

        // Built via the primary constructor directly, with an explicit rate.
        SavingsAccount priya = new SavingsAccount("CUR3001", "Priya Sharma", new BigDecimal("250000"), new BigDecimal("0.035"));
        log.info(() -> "Priya account created, rate=" + priya.getInterestRate());

        BigDecimal rentAmount = new BigDecimal("50000");
        rajesh.debit(rentAmount);
        priya.credit(rentAmount);
        log.info(() -> "Transfer " + rentAmount + " from " + rajesh.getAccountId()
                + " to " + priya.getAccountId() + " SUCCESS");
        log.info(() -> "Rajesh=" + rajesh.getBalance() + " Priya=" + priya.getBalance());

        // Demonstrate the compiler-enforced rule: a blank account is impossible
        // because Account has no no-arg constructor (the following would NOT compile):
        //   SavingsAccount bad = new SavingsAccount() {};  // compile error
    }
}
